(function () {
  'use strict';
  window.WBGrowthUI = function (ctx, helpers) {
    const {D,esc:e,icon,badge,heading,modal,toast}=ctx, GM=window.WBGrowthModel;
    const definitions={reference:{key:'references',name:'参考资料',method:'Reference',icon:'bookmark'},benchmark:{key:'benchmarks',name:'对标',method:'Benchmark',icon:'compass'},research:{key:'research',name:'研究主题',method:'Research',icon:'search'}};
    const labels={all:'全部类型',reference:'参考资料',benchmark:'对标库',research:'研究主题',project:'项目',work:'作品',knowledge:'知识与案例',skill:'Skill',topic:'选题',task:'任务',idea:'想法',news:'公开资讯缓存',tool:'工具',section:'工作台入口'};
    const defaults={positioning:'用 AI 解决工作和生意中的实际问题',audience:'首批面向外贸运营同行',promise:'',pillars:[],series:[]};
    let growth=GM.empty(),ready=false,loading=false,saving=false,loadError='',query='',filter='all',limit=40,pendingDelete=null;
    const drafts={};
    const clone=value=>JSON.parse(JSON.stringify(value));
    const find=(kind,id)=>definitions[kind]?(growth[definitions[kind].key]||[]).find(r=>r.id===id):null;
    const fmt=value=>{if(!value)return '尚未记录';const d=new Date(value);return Number.isNaN(d.getTime())?'尚未记录':d.toLocaleDateString('zh-CN',{timeZone:'America/Los_Angeles'});};
    const safeURL=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}};
    const sourceLink=url=>safeURL(url)?`<a class="growth-source-link" href="${e(safeURL(url))}" target="_blank" rel="noopener noreferrer">查看原链接 ${icon('external-link')}<span>${e(url)}</span></a>`:'<p class="small-caption">未填写可打开的公开原链接。</p>';
    const text=(label,value)=>value?`<section class="growth-detail-section"><h3>${e(label)}</h3><p>${e(value)}</p></section>`:'';
    const tagsHTML=tags=>(tags||[]).length?`<div class="growth-tags">${tags.map(t=>`<span>${e(t)}</span>`).join('')}</div>`:'';
    const disable=()=>!ready||loading||saving?' disabled':'';
    const action=(name,label,kind,id,cls='small-button')=>`<button class="${cls}" data-action="growth-${name}" data-kind="${e(kind)}"${id?` data-id="${e(id)}"`:''}${disable()}>${label}</button>`;
    const close=()=>document.querySelector('#dialog')?.close();
    function formError(form,message){const box=form?.querySelector('[data-growth-error]');if(box){box.textContent=message;box.hidden=!message;}}
    function formBusy(form,busy){const button=form?.querySelector('[type="submit"]');if(button){button.disabled=busy;button.textContent=busy?'正在保存…':'保存';}}
    async function api(options){const res=await fetch('/api/growth',options||{cache:'no-store'});let result;try{result=await res.json();}catch{throw Error('本机返回内容不完整，请稍后重试');}if(!res.ok)throw Object.assign(Error(result?.error||'本机资料暂时不可用'),{status:res.status});return result;}
    async function init(){
      if(loading||saving)return;loading=true;loadError='';ctx.render();
      try{const result=await api();if(!Object.prototype.hasOwnProperty.call(result,'state'))throw Error('没有收到完整资料，已保留当前内容');const next=result.state===null?GM.empty():GM.normalizeState(result.state);growth=next;ready=true;}
      catch(err){loadError=err.message||'本机资料连接失败';toast('资料未能加载：'+loadError);}
      finally{loading=false;ctx.render();}
    }
    async function persist(next,form,message){
      if(saving)return false;if(!ready||loading){formError(form,'本机资料正在连接，请稍后再保存；填写内容已保留。');toast('本机资料正在连接，请稍后再保存');return false;}
      saving=true;formBusy(form,true);formError(form,'');
      try{const result=await api({method:'POST',headers:{'Content-Type':'application/json','X-Workbench-Growth-Revision':String(growth.modifiedAt)},body:JSON.stringify(next)});if(result.saved!==true||!result.state)throw Error('没有收到保存确认，请保留当前输入后重试');const saved=GM.normalizeState(result.state);growth=saved;loadError='';if(form?.getAttribute('id')==='growth-record-form'){const f=new FormData(form),kind=String(f.get('kind')||'');if(definitions[kind]){query='';filter=kind;limit=40;}}saving=false;formBusy(form,false);if(!form||document.querySelector('#'+form.getAttribute('id'))===form)close();toast(message||'已保存');ctx.render();return true;}
      catch(err){const message='保存失败：'+(err.message||'本机服务暂时不可用')+'。原内容和填写内容已保留，可重试。';formError(form,message);toast(message);return false;}
      finally{saving=false;formBusy(form,false);}
    }
    function stateNotice(){
      if(loading)return '<div class="growth-state" role="status" aria-live="polite">正在连接本机资料…</div>';
      if(loadError)return `<div class="growth-state growth-error" role="alert"><div><strong>${ready?'暂时无法重新加载，保留上次内容':'资料尚未连接'}</strong><p>${e(loadError)}。${ready?'当前仍可查看已加载记录。':'请重试连接后再保存，避免覆盖已有资料。'}</p></div><button class="outline-button" data-action="growth-retry">重试加载</button></div>`;
      return '';
    }
    function search(q,kind='all'){return GM.searchRecords({growth,state:ctx.getState(),library:helpers.getLibrary(),news:helpers.getNews(),tools:D?.tools||[],sections:D?.sections||[]},q,kind);}
    function localResults(){
      const all=search(query,filter);
      return !query.trim()&&filter==='all'?all.filter(r=>definitions[r.kind]):all;
    }
    function resultHTML(r){const def=definitions[r.kind],record=def?find(r.kind,r.id):null;return `<article class="growth-result"><div class="growth-result-content"><div class="growth-result-meta"><span>${e(r.sourceLabel||labels[r.kind]||'本机资料')}</span>${record?.status?badge(record.status,'blue'):''}<span>${fmt(r.updatedAt)}</span></div><button class="growth-result-title" data-action="${e(r.action||'growth-open')}" data-kind="${e(r.kind)}" data-id="${e(r.id)}">${e(r.title)}${icon('arrow-up-right')}</button>${r.summary?`<p>${e(r.summary)}</p>`:''}${record?tagsHTML(record.tags):''}</div>${def?`<div class="growth-row-actions">${action('topic','转成选题',r.kind,r.id)}${action('task','加入今天',r.kind,r.id,'text-button')}</div>`:''}</article>`;}
    function resultsHTML(){const results=localResults(),shown=results.slice(0,limit);return `<div class="growth-results-heading"><h3>${query.trim()?'搜索结果':filter==='all'?'已保存的研究资料':labels[filter]||'资料'}</h3><span>${results.length} 条${query.trim()?' · 本机已有资料':''}</span></div>${shown.length?`<div class="growth-results-list">${shown.map(resultHTML).join('')}</div>${results.length>limit?'<button class="outline-button growth-more" data-action="growth-more">再看 40 条</button>':''}`:`<div class="growth-empty"><span class="growth-empty-icon">${icon(query?'search':'bookmark')}</span><h3>${query.trim()?'没有找到匹配资料':'从一条值得留下的来源开始'}</h3><p>${query.trim()?'换个关键词或类型；公开搜索需要你主动打开网页。':'保存原链接、摘要和自己的判断，再决定是否转成选题。'}</p>${action('new','新增参考资料','reference',null,'outline-button')}</div>`}`;}
    function searchURL(){return query.trim()?`https://www.google.com/search?q=${encodeURIComponent(query.trim())}`:'';}
    function publicHTML(){return `<div id="growth-public-search">${searchURL()?`<a class="outline-button" href="${e(searchURL())}" target="_blank" rel="noopener noreferrer">公开搜索 ${icon('external-link')}</a>`:'<span class="growth-search-hint">输入关键词后可打开公开搜索</span>'}<p class="small-caption">会打开公开网页，只使用上方关键词。读完原文后，可手动保存来源与判断。</p></div>`;}
    function research(){return `<section class="growth-workspace">${heading('研究与参考','把有用来源和自己的判断留在一起。',action('new',icon('plus')+'新增资料','reference',null,'primary-button'))}${stateNotice()}<div class="growth-layout"><div class="growth-main"><div class="growth-search-toolbar"><label class="growth-search-field">${icon('search')}<span class="sr-only">搜索本机已有资料</span><input id="growth-search" type="search" autocomplete="off" value="${e(query)}" placeholder="搜索关键词、标签或问题"></label><label class="growth-filter"><span class="sr-only">按资料类型筛选</span><select id="growth-kind" aria-label="资料类型">${Object.entries(labels).map(([key,label])=>`<option value="${key}"${filter===key?' selected':''}>${label}</option>`).join('')}</select></label></div><div class="growth-views" aria-label="研究资料视图">${[['all','全部资料'],['reference','参考资料'],['benchmark','对标库'],['research','研究主题']].map(([key,label])=>`<button data-action="growth-filter" data-value="${key}" aria-pressed="${filter===key}" class="${filter===key?'active':''}">${label}</button>`).join('')}</div><div id="growth-results" aria-live="polite">${ready?resultsHTML():loading?'':'<div class="growth-empty"><h3>先连接本机资料</h3><p>连接恢复后，就能查找、保存和整理来源。</p></div>'}</div></div><aside class="growth-aside"><section class="growth-aside-section"><h3>正在研究什么？</h3><p>先记下问题，再逐步补充来源。</p>${(growth.research||[]).slice(0,4).map(r=>`<button class="growth-research-link" data-action="growth-open" data-kind="research" data-id="${e(r.id)}">${e(r.title)}${icon('chevron-right')}</button>`).join('')||'<p class="small-caption">还没有研究主题。</p>'}${action('new','新建研究主题','research',null,'text-button')}</section><section class="growth-aside-section"><h3>到公开网页找来源</h3>${publicHTML()}</section><section class="growth-aside-section growth-aside-quiet"><h3>看到好内容，拆一拆</h3><p>记录它讲给谁、如何开头、凭什么可信，以及自己可以怎样做得不同。</p>${action('new','新增对标','benchmark',null,'text-button')}</section></aside></div></section>`;}
    function refreshSearch(){const results=document.getElementById('growth-results');if(results&&ready)results.innerHTML=resultsHTML();const publicBox=document.getElementById('growth-public-search');if(publicBox)publicBox.outerHTML=publicHTML();}
    function input(label,name,value='',type='text',required=false,max=5000){return `<label class="form-field">${e(label)}<input type="${type}" name="${name}" value="${e(value)}" maxlength="${max}"${required?' required':''}></label>`;}
    function textarea(label,name,value='',rows=3,max=5000){return `<label class="form-field">${e(label)}<textarea name="${name}" rows="${rows}" maxlength="${max}">${e(value)}</textarea></label>`;}
    function group(label,content,open=false){return `<details class="growth-form-group"${open?' open':''}><summary>${e(label)}</summary><div>${content}</div></details>`;}
    function editor(kind,id){const def=definitions[kind];if(!def)return;if(!ready||loading){toast('请先连接本机资料，再新增或编辑');return;}const r=id?find(kind,id):drafts[kind]||{};if(!r){toast('这条记录已不存在，请刷新列表');return;}let fields=input('标题','title',r.title||'','text',true,160);
      if(kind==='reference')fields+=input('公开原链接（可稍后补充）','url',r.url||'','url',false,2000)+textarea('摘要：原文说了什么？','summary',r.summary,3,8000)+textarea('个人启发：对我有什么用？','note',r.note,3,16000)+group('标签与整理状态',input('标签（用逗号分隔）','tags',(r.tags||[]).join('，'),'text',false,500)+input('状态','status',r.status||'待整理','text',false,80));
      if(kind==='benchmark')fields+=`<div class="growth-form-grid">${input('平台或网站','platform',r.platform||'','text',false,80)}${input('内容形式','benchmarkKind',r.kind||'','text',false,80)}</div>`+input('公开原链接','url',r.url||'','url',false,2000)+textarea('主题：它解决什么问题？','topic',r.topic,3,160)+group('拆解开头、结构与证据',textarea('开头：如何让人愿意看？','hook',r.hook)+textarea('结构：怎样展开？','structure',r.structure,3,8000)+textarea('证据：有什么依据？','evidence',r.evidence,3,8000),!!(r.hook||r.structure||r.evidence))+group('提炼自己的做法',textarea('可借鉴之处','learning',r.learning,3,8000)+textarea('我的差异：准备怎样做？','difference',r.difference,3,8000)+textarea('补充笔记','note',r.note,3,16000)+input('观察日期','observedAt',r.observedAt?String(r.observedAt).slice(0,10):'','date'),!!(r.learning||r.difference));
      if(kind==='research')fields+=textarea('想弄清楚的问题','question',r.question)+textarea('当前判断与待验证点','note',r.note)+group('标签',input('标签（用逗号分隔）','tags',(r.tags||[]).join('，'),'text',false,500));
      modal(id?'编辑'+def.name:'新增'+def.name,`<form id="growth-record-form" class="growth-form"><input type="hidden" name="kind" value="${kind}"><input type="hidden" name="recordId" value="${e(id||'')}">${!id?`<div class="growth-editor-kinds">${Object.entries(definitions).map(([key,value])=>`<button type="button" class="${key===kind?'active':''}" data-action="growth-editor-kind" data-kind="${key}" aria-pressed="${key===kind}">${value.name}</button>`).join('')}</div>`:''}${fields}<p class="growth-form-error" data-growth-error role="alert" hidden></p><button type="button" class="text-button" data-action="growth-retry">重新读取资料（保留填写）</button><div class="dialog-actions"><button class="outline-button" type="button" data-action="close">取消</button><button class="primary-button" type="submit">保存</button></div></form>`,'研究与参考');
    }
    function details(kind,id){const def=definitions[kind],r=find(kind,id);if(!r){toast('没有找到这条记录，请刷新后重试');return;}const topics=(ctx.getState().topics||[]).filter(t=>t.source?.type===kind&&t.source?.id===id);let body=kind==='reference'?text('摘要',r.summary)+text('个人启发',r.note):kind==='research'?text('研究问题',r.question)+text('当前判断与待验证点',r.note):text('平台与形式',[r.platform,r.kind].filter(Boolean).join(' · '))+text('主题',r.topic)+text('开头',r.hook)+text('内容结构',r.structure)+text('证据',r.evidence)+text('可借鉴之处',r.learning)+text('我的差异',r.difference)+text('补充笔记',r.note);
      modal(r.title,`<div class="growth-detail">${badge(def.name,'blue')}${r.status?badge(r.status,'teal'):''}${tagsHTML(r.tags)}${body||'<p class="dialog-lead">还没有写下摘要或判断，可以编辑补充。</p>'}${kind!=='research'?`<section class="growth-detail-section"><h3>原链接</h3>${sourceLink(r.url)}</section>`:''}<section class="growth-detail-section"><h3>关联选题</h3>${topics.length?`<div class="growth-related">${topics.map(t=>`<button class="small-button" data-action="topic-edit" data-id="${e(t.id)}">${e(t.title)}</button>`).join('')}</div>`:'<p>还没有从这条资料创建选题。</p>'}</section><p class="small-caption">${kind==='benchmark'&&r.observedAt?'观察 '+e(r.observedAt)+' · ':''}更新 ${fmt(r.updatedAt)}</p><div class="growth-detail-actions">${action('topic','转成选题',kind,id,'primary-button')}${action('task','加入今天',kind,id,'outline-button')}${action('edit','编辑',kind,id,'text-button')}${action('delete','删除',kind,id,'text-button growth-delete')}</div></div>`,'研究与参考');
    }
    function profileView(){const p=growth.profile||{},isEmpty=!p.positioning&&!p.audience&&!p.promise&&!(p.pillars||[]).length&&!(p.series||[]).length;return isEmpty?clone(defaults):p;}
    function ip(){const p=profileView();return `<section class="growth-workspace growth-ip">${heading('我的 IP 方向','把定位和内容系列写清楚，让下一条内容有所依循。',`<button class="primary-button" data-action="growth-profile-edit"${disable()}>编辑方向</button>`)}${stateNotice()}<div class="growth-ip-layout"><section class="growth-position"><span class="growth-eyebrow">我想帮助谁，解决什么问题</span><h3>${e(p.positioning||'尚未填写定位')}</h3><dl><div><dt>首批受众</dt><dd>${e(p.audience||'尚未填写')}</dd></div><div><dt>价值承诺</dt><dd>${e(p.promise||'尚未填写，可从真实做过的事情开始。')}</dd></div></dl><p class="small-caption">方向可以调整；内容中的操作、结果和限制仍需分别核实。</p></section><div class="growth-ip-lists"><section class="growth-aside-section"><h3>内容支柱</h3>${p.pillars?.length?`<ul class="growth-profile-list">${p.pillars.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:'<p>还没有整理。可以先写你愿意长期回答的几类问题。</p>'}</section><section class="growth-aside-section"><h3>持续做的系列</h3>${p.series?.length?`<ul class="growth-profile-list">${p.series.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:'<p>还没有系列。先从一个有资料、有步骤的真实案例开始。</p>'}</section></div></div></section>`;}
    function profileEditor(){if(!ready||loading){toast('请先连接本机资料，再编辑方向');return;}const p=profileView();modal('编辑我的 IP 方向',`<form id="growth-profile-form" class="growth-form">${textarea('定位：我关注什么问题？','positioning',p.positioning,2)}${textarea('受众：先讲给谁听？','audience',p.audience,2)}${textarea('价值承诺：读者能得到什么？','promise',p.promise,3)}${group('内容支柱与系列',textarea('内容支柱（每行一个）','pillars',(p.pillars||[]).join('\n'))+textarea('持续做的系列（每行一个）','series',(p.series||[]).join('\n')),true)}<p class="growth-form-error" data-growth-error role="alert" hidden></p><button type="button" class="text-button" data-action="growth-retry">重新读取资料（保留填写）</button><div class="dialog-actions"><button class="outline-button" type="button" data-action="close">取消</button><button class="primary-button" type="submit">保存</button></div></form>`,'IP 与内容');}
    function handleClick(name,el){if(!name.startsWith('growth-'))return false;const {kind,id}=el.dataset||{};
      if(name==='growth-retry'){void init().then(()=>{if(ready&&!loadError){const form=document.querySelector('#growth-record-form')||document.querySelector('#growth-profile-form');formError(form,'');toast('已读取最新资料，当前填写仍保留，可继续保存');}});return true;}
      if(name==='growth-filter'){filter=Object.hasOwn(labels,el.dataset.value)?el.dataset.value:'all';limit=40;ctx.render();return true;}
      if(name==='growth-more'){limit+=40;refreshSearch();return true;}
      if(saving){toast('正在保存这次修改，请稍候');return true;}
      if(name==='growth-editor-kind'){const form=document.querySelector('#growth-record-form');if(form){const data=recordInput(new FormData(form));if(!data.id)drafts[data.kind]=data.input;}editor(kind||'reference');return true;}
      if(name==='growth-new'||name==='growth-edit'){editor(kind||'reference',name==='growth-edit'?id:null);return true;}
      if(name==='growth-profile-edit'){profileEditor();return true;}
      if(name==='growth-open'){if(definitions[kind])details(kind,id);else helpers.openRecord(kind,id);return true;}
      const r=find(kind,id);if(!r){toast('这条记录已不存在，请刷新列表');return true;}
      if(name==='growth-topic'){helpers.createTopic({title:r.title,problem:r.summary||r.question||r.topic||'',steps:r.learning||r.note||'',source:{type:kind,id:r.id,label:r.title,url:r.url||''}});return true;}
      if(name==='growth-task'){helpers.addTask('研究：'+r.title,[r.summary||r.question||r.topic,r.note||r.learning,r.url].filter(Boolean).join('\n'),20,{sourceType:kind,sourceId:r.id,evidence:'留下原文依据、一条个人判断和下一步。'});return true;}
      if(name==='growth-delete'){pendingDelete={kind,id};modal('删除这条'+definitions[kind].name+'？',`<p class="dialog-lead">${e(r.title)}</p><p>只删除当前这条本机记录。原链接和已经创建的选题、任务会保留。</p><p class="growth-form-error" data-growth-error role="alert" hidden></p><button type="button" class="text-button" data-action="growth-retry">重新读取资料（保留填写）</button><div class="dialog-actions"><button class="outline-button" data-action="close">保留</button><button class="primary-button" data-action="growth-delete-confirm" data-kind="${kind}" data-id="${e(id)}">确认删除此条</button></div>`,'确认当前记录');return true;}
      if(name==='growth-delete-confirm'){if(pendingDelete?.kind!==kind||pendingDelete?.id!==id){toast('请重新打开当前记录确认删除');return true;}try{const next=GM['delete'+definitions[kind].method](growth,id);void persist(next,null,'已删除当前记录').then(saved=>{if(saved)pendingDelete=null;});}catch(err){toast(err.message);}return true;}
      return false;
    }
    function recordInput(f){const get=key=>String(f.get(key)||'').trim(),kind=get('kind'),tags=()=>get('tags').split(/[,，;；\n]/).map(x=>x.trim()).filter(Boolean),input={title:get('title')};if(kind==='reference')Object.assign(input,{url:get('url'),summary:get('summary'),note:get('note'),tags:tags(),status:get('status')||'待整理'});if(kind==='research')Object.assign(input,{question:get('question'),note:get('note'),tags:tags()});if(kind==='benchmark'){for(const key of ['platform','url','topic','hook','structure','evidence','learning','difference','note','observedAt'])input[key]=get(key);input.kind=get('benchmarkKind');}return {kind,id:get('recordId'),input};}
    function handleSubmit(form){const formId=form.getAttribute('id');if(!['growth-record-form','growth-profile-form'].includes(formId))return false;if(saving){toast('正在保存，请稍候');return true;}if(!ready||loading){formError(form,'本机资料正在连接，请稍后再保存；填写内容已保留。');return true;}const f=new FormData(form),get=key=>String(f.get(key)||'').trim(),lines=key=>get(key).split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
      try{let next,recordKind;if(formId==='growth-profile-form')next=GM.updateProfile(growth,{positioning:get('positioning'),audience:get('audience'),promise:get('promise'),pillars:lines('pillars'),series:lines('series')});else{const {kind,id,input}=recordInput(f),def=definitions[kind];if(!def)throw Error('资料类型无效，请重新打开编辑');if(!input.title)throw Error('请先填写标题');recordKind=kind;next=id?GM['update'+def.method](growth,id,input):GM['add'+def.method](growth,input);}void persist(next,form,'已保存到本机资料').then(saved=>{if(saved&&recordKind)delete drafts[recordKind];});}
      catch(err){formError(form,err.message);toast(err.message);}return true;
    }
    function handleInput(input){if(input.id==='growth-search'){query=input.value||'';limit=40;refreshSearch();return true;}if(input.id==='growth-kind'){filter=Object.hasOwn(labels,input.value)?input.value:'all';limit=40;ctx.render();return true;}return false;}
    function openSearch(value){query=typeof value==='string'?value:'';filter='all';limit=40;ctx.go('research');}
    return {init,research,ip,handleClick,handleSubmit,handleInput,search,openSearch,getState:()=>clone(growth),isReady:()=>ready};
  };
})();
